BEGIN;

CREATE TABLE "auctions" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Title" varchar(200) NOT NULL,
  "Description" varchar(1000) DEFAULT NULL,
  "JewelryItemId" INTEGER NOT NULL,
  "SellerId" INTEGER NOT NULL,
  "StartingBid" decimal(18,2) NOT NULL,
  "ReservePrice" decimal(18,2) DEFAULT NULL,
  "BidIncrement" decimal(18,2) NOT NULL,
  "BuyNowPrice" decimal(18,2) DEFAULT NULL,
  "StartTime" TIMESTAMP(6) NOT NULL,
  "EndTime" TIMESTAMP(6) NOT NULL,
  "Status" INTEGER NOT NULL,
  "CurrentBid" decimal(18,2) NOT NULL,
  "LeadingBidderId" INTEGER DEFAULT NULL,
  "WinningBidderId" INTEGER DEFAULT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL,
  "UpdatedAt" TIMESTAMP(6) DEFAULT NULL,
  "ViewCount" INTEGER DEFAULT 0,
  "TotalBids" INTEGER DEFAULT 0,
  "IsPublished" BOOLEAN DEFAULT FALSE,
  "IsFeatured" BOOLEAN DEFAULT FALSE
);

CREATE TABLE "bids" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "AuctionId" INTEGER NOT NULL,
  "BidderId" INTEGER NOT NULL,
  "Amount" decimal(18,2) NOT NULL,
  "Status" INTEGER NOT NULL,
  "BidTime" TIMESTAMP(6) NOT NULL,
  "IsAutomaticBid" BOOLEAN NOT NULL,
  "MaxAutoBidAmount" decimal(18,2) DEFAULT NULL
);

CREATE TABLE "contact_inquiries" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Name" varchar(100) NOT NULL,
  "Email" varchar(255) NOT NULL,
  "MobileNumber" varchar(20) DEFAULT NULL,
  "Enquiry" text NOT NULL,
  "Status" VARCHAR(20) DEFAULT 'Pending' CHECK ("Status" IN ('Pending','InProgress','Resolved','Closed')),
  "Priority" VARCHAR(20) DEFAULT 'Medium' CHECK ("Priority" IN ('Low','Medium','High','Urgent')),
  "AssignedToUserId" INTEGER DEFAULT NULL,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP DEFAULT NULL,
  "RespondedAt" TIMESTAMP DEFAULT NULL,
  "Notes" text DEFAULT NULL
);

CREATE TABLE "jewelryimages" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "JewelryItemId" INTEGER NOT NULL,
  "ImageUrl" varchar(500) NOT NULL,
  "AltText" varchar(200) DEFAULT NULL,
  "IsPrimary" BOOLEAN NOT NULL,
  "DisplayOrder" INTEGER NOT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL
);

CREATE TABLE "jewelryitems" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Name" varchar(200) NOT NULL,
  "Description" varchar(2000) DEFAULT NULL,
  "Type" INTEGER NOT NULL,
  "PrimaryMaterial" INTEGER NOT NULL,
  "Brand" varchar(100) DEFAULT NULL,
  "Weight" decimal(8,3) DEFAULT NULL,
  "Dimensions" varchar(50) DEFAULT NULL,
  "Condition" INTEGER NOT NULL,
  "YearMade" INTEGER DEFAULT NULL,
  "Origin" varchar(100) DEFAULT NULL,
  "CertificationDetails" varchar(500) DEFAULT NULL,
  "EstimatedValue" decimal(18,2) NOT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL
);

CREATE TABLE "notifications" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER NOT NULL,
  "Type" varchar(100) NOT NULL,
  "Title" varchar(200) NOT NULL,
  "Message" varchar(1000) NOT NULL,
  "IsRead" BOOLEAN NOT NULL DEFAULT FALSE,
  "EntityType" varchar(50) DEFAULT NULL,
  "EntityId" INTEGER DEFAULT NULL,
  "Amount" decimal(18,2) DEFAULT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  "ReadAt" TIMESTAMP(6) DEFAULT NULL,
  "ActionUrl" varchar(500) DEFAULT NULL,
  "ActionLabel" varchar(100) DEFAULT NULL,
  "ActionCancelUrl" varchar(500) DEFAULT NULL,
  "ActionCancelLabel" varchar(100) DEFAULT NULL
);

CREATE TABLE "payments" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "AuctionId" INTEGER NOT NULL,
  "PayerId" INTEGER NOT NULL,
  "Amount" decimal(18,2) NOT NULL,
  "AuctioneerFee" decimal(18,2) DEFAULT NULL,
  "ProcessingFee" decimal(18,2) DEFAULT NULL,
  "TotalAmount" decimal(18,2) NOT NULL,
  "Method" INTEGER NOT NULL,
  "Status" INTEGER NOT NULL,
  "TransactionId" varchar(100) DEFAULT NULL,
  "PaymentGatewayResponse" varchar(100) DEFAULT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL,
  "ProcessedAt" TIMESTAMP(6) DEFAULT NULL,
  "PaymentDeadline" TIMESTAMP(6) DEFAULT NULL,
  "BidId" INTEGER DEFAULT NULL
);

CREATE TABLE "payment_methods" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER NOT NULL,
  "Type" varchar(50) NOT NULL,
  "Brand" varchar(100) DEFAULT NULL,
  "Last4" varchar(4) DEFAULT NULL,
  "ExpiryDate" varchar(7) DEFAULT NULL,
  "Email" varchar(255) DEFAULT NULL,
  "BankName" varchar(255) DEFAULT NULL,
  "AccountNumber" varchar(100) DEFAULT NULL,
  "IsDefault" BOOLEAN NOT NULL DEFAULT FALSE,
  "IsActive" BOOLEAN NOT NULL DEFAULT TRUE,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  "UpdatedAt" TIMESTAMP(6) DEFAULT NULL
);

CREATE TABLE "social_shares" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER DEFAULT NULL,
  "AuctionId" INTEGER DEFAULT NULL,
  "Platform" varchar(50) NOT NULL,
  "ShareType" varchar(20) NOT NULL,
