  "UserAgent" varchar(500) DEFAULT NULL,
  "IpAddress" varchar(50) DEFAULT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
);

CREATE TABLE "users" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Username" varchar(50) NOT NULL,
  "Email" varchar(255) NOT NULL,
  "PasswordHash" TEXT NOT NULL,
  "PhoneNumber" varchar(20) DEFAULT NULL,
  "Role" INTEGER NOT NULL DEFAULT 0,
  "Status" INTEGER NOT NULL DEFAULT 0,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  "LastLogin" TIMESTAMP(6) DEFAULT NULL,
  "UpdatedAt" TIMESTAMP(6) DEFAULT NULL,
  "EmailVerified" BOOLEAN NOT NULL DEFAULT FALSE,
  "EmailVerificationCode" varchar(6) DEFAULT NULL,
  "EmailVerificationCodeExpiry" TIMESTAMP(6) DEFAULT NULL
);

CREATE TABLE "user_activities" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER NOT NULL,
  "ActivityType" varchar(50) NOT NULL,
  "Description" varchar(500) NOT NULL,
  "EntityType" varchar(50) DEFAULT NULL,
  "EntityId" INTEGER DEFAULT NULL,
  "Amount" decimal(18,2) DEFAULT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
);

CREATE TABLE "user_preferences" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER NOT NULL,
  "EmailNotifications" BOOLEAN NOT NULL DEFAULT TRUE,
  "SmsNotifications" BOOLEAN NOT NULL DEFAULT FALSE,
  "PushNotifications" BOOLEAN NOT NULL DEFAULT TRUE,
  "BidNotifications" BOOLEAN NOT NULL DEFAULT TRUE,
  "AuctionEndNotifications" BOOLEAN NOT NULL DEFAULT TRUE,
  "NewsletterSubscription" BOOLEAN NOT NULL DEFAULT TRUE,
  "TwoFactorEnabled" BOOLEAN NOT NULL DEFAULT FALSE,
  "Currency" varchar(10) NOT NULL DEFAULT 'USD',
  "Language" varchar(10) NOT NULL DEFAULT 'en',
  "Timezone" varchar(50) NOT NULL DEFAULT 'UTC',
  "PrivacyLevel" INTEGER NOT NULL DEFAULT 0,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  "UpdatedAt" TIMESTAMP(6) DEFAULT NULL
);

CREATE TABLE "user_profiles" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER NOT NULL,
  "FirstName" varchar(50) DEFAULT NULL,
  "LastName" varchar(50) DEFAULT NULL,
  "Address" varchar(500) DEFAULT NULL,
  "City" varchar(100) DEFAULT NULL,
  "State" varchar(100) DEFAULT NULL,
  "ZipCode" varchar(20) DEFAULT NULL,
  "Country" varchar(100) DEFAULT NULL,
  "ProfileImageUrl" varchar(500) DEFAULT NULL,
  "DateOfBirth" date DEFAULT NULL,
  "Bio" varchar(1000) DEFAULT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  "UpdatedAt" TIMESTAMP(6) DEFAULT NULL
);

CREATE TABLE "wishlists" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "UserId" INTEGER NOT NULL,
  "JewelryItemId" INTEGER NOT NULL,
  "CreatedAt" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
);

